steps.codeExample:
#include "raylib.h"

int main() {
    InitWindow(800, 450, "Meu Jogo C++");
    SetTargetFPS(60);

    float x = 100.0f;
    while (!WindowShouldClose()) {
        x += 200.0f * GetFrameTime(); // Movimento independente de FPS!

        BeginDrawing();
        ClearBackground(BLACK);
        DrawCircle((int)x, 225, 20, GREEN);
        EndDrawing();
    }
    CloseWindow();
}

